function onChangeTab$Form(sender, e) {
	sender.parentForm.focusWhenTabChanged([#FOCUSTAB#]);				
}[#TabControl#]
function active$VoucherFilter$(f) {
	f.add_onResponseComplete(on$Filter$ResponseComplete); [#TabControl#]			
	f._tabContainer.add_activeTabChanged(onChangeTab$Form);
	f._tabContainer._loaded = true;[#TabControl#][#TRANSACTION#]
	&FilterExpression;[#TRANSACTION#]
	//changeLookupReadonly(f, 'ma_dvcs');
}
function close$VoucherFilter$(f) {
	try {f.remove_onResponseComplete(on$Filter$ResponseComplete);} catch (ex) {}[#TabControl#]
	if (f._tabContainer) try {f._tabContainer.remove_activeTabChanged(onChangeTab$Form);} catch (ex) {}[#TabControl#]
}
function on$Filter$ResponseComplete(sender, e) {
	var f = e.object, context = e.type.Context, result = e.type.Result;
